import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { summarizeTrades } from '../src/domain.js';
import { selectSyntheticChartData } from '../src/synthetic-market.js';
import { getAvailableIntervals, selectChartData } from '../src/market-data.js';
import { validateContext } from '../server/contracts.js';

// This committed public fixture is generated by the same script that creates
// the user's download. Tests never depend on an external workspace directory.
const bundle = JSON.parse(await readFile(new URL('../public/fixtures/complete-synthetic-review.json', import.meta.url), 'utf8'));
const { trades, marketData } = bundle;
const timestamp = value => Date.parse(`${value}+08:00`) / 1000;
const localDay = value => new Date((value + 28800) * 1000).toISOString().slice(0, 10);
const cents = value => Math.round(value * 100);
const barValues = bar => Object.fromEntries(['open', 'high', 'low', 'close'].map(key => [key, bar[key]]));
function expectedOhlc(points) {
  return { open: points[0].price, high: Math.max(...points.map(point => point.price)), low: Math.min(...points.map(point => point.price)), close: points.at(-1).price };
}
function holdingCycles(rows) {
  const cycles = []; let position = 0, cycle = [];
  for (const trade of rows) {
    cycle.push(trade); position += trade.side === 'buy' ? trade.quantity : -trade.quantity;
    if (position === 0) { cycles.push(cycle); cycle = []; }
  }
  assert.equal(cycle.length, 0, 'every cycle must close');
  return cycles;
}

test('complete synthetic review fixture is explicit, stable and accepted as a matching bundle', () => {
  assert.equal(bundle.format, 'huikan-review-bundle'); assert.equal(bundle.version, 1);
  assert.equal(marketData.synthetic, true); assert.equal(marketData.symbol, 'SIM086');
  assert.equal(trades.length, 42); assert.equal(marketData.pricePoints.length, 4300);
  assert.equal(new Set(marketData.pricePoints.map(point => localDay(point.time))).size, 86);
  const context = validateContext({ trades, contexts: {}, origin: '合成资料验收', marketData });
  assert.equal(context.marketData.provenance, 'file-synthetic');
  assert.deepEqual(getAvailableIntervals({ trades, marketData }), ['15m', '4H', '1D', '1W', '1M']);
  assert.deepEqual(getAvailableIntervals({ trades: [{ ...trades[0], symbol: 'OTHER' }], marketData }), []);
});

test('all 42 executions match their independent price observation and obey long-only T+1 inventory', () => {
  const points = new Map(marketData.pricePoints.map(point => [point.time, point.price]));
  const lots = []; let position = 0, previous = -Infinity, sales = 0;
  for (const trade of trades) {
    const at = timestamp(trade.time), day = trade.time.slice(0, 10);
    assert.ok(at > previous, `execution ${trade.id} must be chronological`); previous = at;
    assert.equal(trade.price, points.get(at), `execution price ${trade.id}`);
    assert.equal(trade.quantity % 100, 0, `stock lot size ${trade.id}`);
    if (trade.side === 'buy') { position += trade.quantity; lots.push({ day, quantity: trade.quantity }); }
    else {
      sales++; let left = trade.quantity;
      assert.ok(lots.filter(lot => lot.day < day).reduce((sum, lot) => sum + lot.quantity, 0) >= left, `T+1 ${trade.id}`);
      for (const lot of lots) { if (lot.day >= day || left === 0) continue; const used = Math.min(lot.quantity, left); lot.quantity -= used; left -= used; }
      assert.equal(left, 0); position -= trade.quantity;
    }
    assert.ok(position >= 0, `negative inventory ${trade.id}`);
  }
  assert.equal(position, 0); assert.equal(sales, 18); assert.equal(lots.reduce((sum, lot) => sum + lot.quantity, 0), 0);
});

test('six closed cycles reconcile fee assumptions and exact net cash without treating six cycles as one return', () => {
  const cycles = holdingCycles(trades);
  assert.equal(cycles.length, 6); assert.ok(cycles.every(cycle => cycle.length === 7));
  const expectedProfits = [74651, -135791, 7572, 96864, 177414, 5485];
  let totalCash = 0, totalFees = 0;
  cycles.forEach((cycle, index) => {
    let cash = 0, fees = 0;
    for (const trade of cycle) {
      const amountCents = cents(trade.price) * trade.quantity;
      const amount = amountCents / 100;
      assert.equal(cents(trade.fee), cents(Math.max(5, amount * 0.00025) + amount * 0.00001 + (trade.side === 'sell' ? amount * 0.0005 : 0)));
      fees += cents(trade.fee); cash += (trade.side === 'sell' ? amountCents : -amountCents) - cents(trade.fee);
    }
    const summary = summarizeTrades(cycle);
    assert.equal(summary.position, 0); assert.equal(summary.isComplete, true);
    assert.equal(cents(summary.netPnl), cash); assert.equal(cents(summary.fees), fees); assert.equal(cash, expectedProfits[index]);
    totalCash += cash; totalFees += fees;
  });
  assert.equal(totalCash, 226195); assert.equal(totalFees, 40605);
  const all = summarizeTrades(trades);
  assert.equal(all.isComplete, true); assert.equal(all.cycleCount, 6);
  assert.equal(cents(all.netPnl), totalCash); assert.equal(all.returnPct, null);
  assert.equal(cents(all.sellAmount) - cents(all.buyAmount) - cents(all.fees), totalCash);
});

test('four-hour and daily OHLC reconcile to the original observations at every completed window', () => {
  for (const interval of ['4H', '1D']) {
    const full = selectSyntheticChartData({ trades, marketData, interval });
    assert.equal(full.candles.length, interval === '4H' ? 172 : 86);
    assert.equal(full.markers.length, trades.length); assert.equal(full.currentBar, null);
    for (const candle of full.candles) {
      const start = Date.parse(candle.startAt) / 1000, end = Date.parse(candle.endAt) / 1000;
      const observations = marketData.pricePoints.filter(point => point.time >= start && point.time <= end);
      assert.deepEqual(barValues(candle), expectedOhlc(observations));
      const replay = selectSyntheticChartData({ trades, marketData, interval, cutoff: candle.endAt, showFuture: false });
      const matched = replay.candles.find(item => item.time === candle.time);
      assert.deepEqual(barValues(matched), barValues(candle)); assert.equal(matched.isPartial, undefined);
    }
  }
});

test('each decision retains its unfinished candle and hides every later price and execution', () => {
  for (const trade of trades) {
    const limit = timestamp(trade.time);
    for (const interval of ['4H', '1D', '1W', '1M']) {
      const view = selectChartData({ trades, marketData, interval, cutoff: trade.time, showFuture: false, mode: 'import' });
      const current = view.candles.at(-1), start = Date.parse(current.startAt) / 1000;
      const observations = marketData.pricePoints.filter(point => point.time >= start && point.time <= limit);
      assert.ok(view.currentBar, `${trade.id} ${interval} must retain current candle`);
      assert.equal(view.currentBar.status, 'partial');
      assert.deepEqual(view.currentBar.ohlc, expectedOhlc(observations));
      assert.equal(view.currentBar.ohlc.close, trade.price);
      assert.equal(view.markers.length, trades.filter(item => timestamp(item.time) <= limit).length);
      assert.ok(view.markers.some(marker => marker.id === trade.id));
      for (const candle of view.candles) assert.ok(Date.parse(candle.lastObservedAt) / 1000 <= limit);
    }
  }
});

test('mutating all future observations cannot change any decision-time candle or marker', () => {
  for (const trade of trades) {
    const limit = timestamp(trade.time);
    const changed = { ...marketData, pricePoints: marketData.pricePoints.map(point => point.time > limit ? { ...point, price: point.price * 10 + 123 } : point) };
    for (const interval of ['4H', '1D', '1W', '1M']) {
      const options = { trades, cutoff: trade.time, interval, showFuture: false };
      assert.deepEqual(selectSyntheticChartData({ ...options, marketData: changed }), selectSyntheticChartData({ ...options, marketData }));
    }
  }
});

test('strict bundle validation rejects bad observations, mismatched scope and real-source disguises', () => {
  const validate = data => validateContext({ trades, contexts: {}, marketData: data });
  assert.throws(() => validate({ ...marketData, synthetic: false }), /合成/);
  assert.throws(() => validate({ ...marketData, symbol: 'REAL001' }), /合成/);
  assert.throws(() => validate({ ...marketData, pricePoints: [...marketData.pricePoints].reverse() }), /升序/);
  assert.throws(() => validate({ ...marketData, pricePoints: [{ ...marketData.pricePoints[0], price: 0 }] }));
  assert.throws(() => validate({ ...marketData, pricePoints: [{ time: timestamp('2025-06-03T12:00'), price: 42 }] }), /交易时段/);
  assert.throws(() => validate({ ...marketData, pricePoints: [{ time: timestamp('2025-06-07T10:00'), price: 42 }] }), /交易时段/);
});

test('chart adapter rejects impossible cutoffs and ignores malformed or off-session observations safely', () => {
  for (const cutoff of ['2025-06-31T09:45', '2025-09-02T24:00', '2025-09-02', 'bad-time', Infinity]) {
    assert.deepEqual(selectSyntheticChartData({ trades, marketData, cutoff, showFuture: false }), { candles: [], markers: [], currentBar: null });
  }
  const invalid = [null, { time: Infinity, price: 99 }, { time: 1e17, price: 99 }, { time: NaN, price: 99 }, { time: timestamp('2025-06-03T12:00'), price: 99 }, { time: timestamp('2025-06-07T10:00'), price: 99 }, { ...marketData.pricePoints[0], price: -1 }];
  assert.deepEqual(selectSyntheticChartData({ trades, marketData: { ...marketData, pricePoints: [...marketData.pricePoints, ...invalid] } }), selectSyntheticChartData({ trades, marketData }));
  assert.deepEqual(selectSyntheticChartData({ trades, marketData: { ...marketData, pricePoints: invalid } }), { candles: [], markers: [], currentBar: null });
  const offset = new Date(timestamp(trades[0].time) * 1000).toISOString();
  assert.deepEqual(selectSyntheticChartData({ trades, marketData, cutoff: offset, showFuture: false }), selectSyntheticChartData({ trades, marketData, cutoff: trades[0].time, showFuture: false }));
});

test('markers outside declared trading sessions are omitted and monthly close uses the last weekday', () => {
  const day = trades[0].time.slice(0, 10);
  const outside = ['09:00', '12:00', '12:45', '15:30', '21:00'].map((clock, index) => ({ ...trades[0], id: `off-session-${index}`, time: `${day}T${clock}` }));
  const view = selectSyntheticChartData({ trades: [...trades, ...outside], marketData });
  assert.equal(view.markers.length, trades.length);
  const lastWeekday = selectSyntheticChartData({ trades, marketData, interval: '1M', cutoff: '2025-08-29T15:00', showFuture: false });
  const august = lastWeekday.candles.find(bar => bar.time === '2025-08-01');
  assert.equal(august.endAt, '2025-08-29T15:00:00+08:00'); assert.equal(august.isPartial, undefined);
  assert.equal(lastWeekday.currentBar, null);
});
